<section><h1 class="h3 mb-3">订单支付</h1><div class="card p-4"><div class="d-flex justify-content-between mb-3"><span><?=h($order['title'])?></span><strong><?=money($order['pay_amount'])?></strong></div><div class="small text-muted mb-3">原价 <?=money($order['amount'])?> · 会员折扣 <?=money($order['discount'])?> · 优惠码优惠 <?=money(isset($order['coupon_discount']) ? $order['coupon_discount'] : 0)?></div><form method="post"><?=csrf_field()?><label class="form-label">支付方式</label><select name="gateway" class="form-select mb-3"><option value="balance">余额支付（<?=money($user['balance'])?>）</option><?php foreach ($gateways as $gateway): ?><option value="<?=h($gateway['code'])?>"><?=h($gateway['name'])?><?php if (!empty($gateway['fee_rate'])): ?>（手续费 <?=h($gateway['fee_rate'])?>%）<?php endif; ?></option><?php endforeach; ?></select><div class="form-help mb-3">余额支付将在余额充足时立即完成；优惠码失效时系统会阻止支付并提示处理方式。</div><button class="btn btn-primary">继续支付</button></form><a class="btn btn-link mt-2" href="<?=h(url_to('index/user/balance'))?>">余额不足？去充值</a></div></section>
